// A Sphinx counts the types it can see: every card in the army except the
// Sphinx card doing the looking. A second Sphinx is therefore a type it counts.
const scoreSphinxAt = (army: Card[], index: number): number =>
  BASE_SCORE +
  varietyBonusFor(countDistinctTypes(army.filter((_, i) => i !== index)));

export const scoreArmy = (army: Card[]): number =>
  army.reduce(
    (total, card, index) =>
      isSphinx(card) ? total + scoreSphinxAt(army, index) : total,
    0,
  );

